#pragma once

#include <cstdint>

// The flags behind the counters of the progress and collection panels. The tables are generated by
// tools/gen_progress.py.
namespace Data
{
    enum class QuestKind : uint8_t
    {
        Main,
        Shrine, // the quests that lead to a shrine
        Side,
        Count
    };

    struct Quest
    {
        uint32_t startHash;    // CRC32 of <name>_Activated, set when the quest is taken
        uint32_t finishHash;   // CRC32 of the flag of its last step, set when it is done
        uint32_t requiresHash; // CRC32 of the flag that has to be set before it can be taken; 0 for none
        uint8_t kind;          // QuestKind
        uint8_t dlc;           // 1 for the quests of the Expansion Pass
        int8_t region;         // where it is taken (Regions.h), for the shrine and side quests of the base game; else -1
    };

    extern const Quest Quests[];
    extern const int QuestsCount;

    // MainFieldDungeon_<actor>_<hash id>, set when the chest is opened; sorted.
    extern const uint32_t DivineBeastChestFlags[];
    extern const int DivineBeastChestFlagsCount;
    extern const uint32_t FinalTrialChestFlags[]; // the last dungeon of the Champions' Ballad
    extern const int FinalTrialChestFlagsCount;

    // The sections of the Hyrule Compendium, in the game's order.
    enum class CompendiumCategory : uint8_t
    {
        Creatures,
        Monsters,
        Materials,
        Equipment,
        Treasure,
        Count
    };

    enum CompendiumFlag : uint8_t
    {
        CompendiumDlc = 1,       // an entry the Champions' Ballad adds
        CompendiumMasterMode = 2 // an entry only Master Mode has
    };

    struct CompendiumEntry
    {
        uint32_t hash;    // CRC32 of IsRegisteredPictureBook_<actor>, set when the entry has a picture
        uint8_t category; // CompendiumCategory
        uint8_t flags;    // CompendiumFlag
    };

    extern const CompendiumEntry CompendiumEntries[]; // sorted by hash
    extern const int CompendiumEntriesCount;

    // The armor that can be had without amiibo. Every level of an upgraded piece has a flag of its own
    // (IsGet_<actor>, set when it is first obtained): the piece is owned when any of them is set.
    struct ArmorFlag
    {
        uint32_t hash;
        uint8_t piece; // 0 to ArmorPiecesCount - 1
        uint8_t dlc;   // 1 for a piece of the Expansion Pass
    };

    extern const ArmorFlag ArmorFlags[]; // in the order of the pieces
    extern const int ArmorFlagsCount;
    extern const int ArmorPiecesCount;

    // IsPlayed_Demo126_0 to _138_0: the scene of each memory spot was played.
    extern const uint32_t MemoryFlags[];
    extern const int MemoryFlagsCount;
    // IsGet_MemoryPhoto_NNN: the pictures in the album that lead to the memories.
    extern const uint32_t MemoryPhotoFlags[];
    extern const int MemoryPhotoFlagsCount;
}
